begin;
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(not has_function_privilege('anon','public.get_education_run(uuid)','execute'),'Anonymous progress denied');
insert into auth.users(id,email) values('c1700000-0000-4000-8000-000000000001','progress-a@example.invalid'),('c1700000-0000-4000-8000-000000000002','progress-b@example.invalid');
insert into public.projects(id,owner_id,title,mode,draft_input) values('c1710000-0000-4000-8000-000000000001','c1700000-0000-4000-8000-000000000001','Progress fixture','education','{"referenceNotes":"PRIVATE_PROGRESS_INPUT"}'),('c1710000-0000-4000-8000-000000000002','c1700000-0000-4000-8000-000000000001','Other mode','software','{}');
select set_config('request.jwt.claims','{"sub":"c1700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.get_education_run('c1710000-0000-4000-8000-000000000001'),null::jsonb,'No generation has no progress');
select throws_ok($$select public.get_education_run('c1710000-0000-4000-8000-000000000002')$$,'42501',null::text,'Non-Education project denied');
insert into public.revisions(id,project_id,owner_id,revision_number,input_hash,request_kind,target_seconds,orientation,voice_profile_id,schema_version,prompt_version,composition_version) values('c1720000-0000-4000-8000-000000000001','c1710000-0000-4000-8000-000000000001','c1700000-0000-4000-8000-000000000001',1,repeat('a',64),'initial',60,'landscape','Kore',1,'v1','v1');
insert into public.jobs(id,project_id,owner_id,revision_id,kind,status,available_at) values('c1730000-0000-4000-8000-000000000001','c1710000-0000-4000-8000-000000000001','c1700000-0000-4000-8000-000000000001','c1720000-0000-4000-8000-000000000001','generation','waiting_worker',now()+interval '1 year');
update public.workers set enabled=false;
select is(public.get_education_run('c1710000-0000-4000-8000-000000000001')->>'workerStatus','not_configured','No compatible executor is explicit');
insert into public.workers(id,label,enabled,protocol_version,last_seen_at,capabilities,health) values('c1740000-0000-4000-8000-000000000001','Progress worker',true,1,now()-interval '5 minutes','{"executionReady":true,"modes":["education"],"orientations":["landscape"],"schemaVersions":[1],"compositionVersion":"v1"}','{"executionReady":true}');
select is(public.get_education_run('c1710000-0000-4000-8000-000000000001')->>'workerStatus','offline','Old heartbeat is offline');
update public.workers set last_seen_at=now() where id='c1740000-0000-4000-8000-000000000001';
select is(public.get_education_run('c1710000-0000-4000-8000-000000000001')->>'workerStatus','online','Fresh ready worker is online');
update public.workers set health='{"executionReady":false}' where id='c1740000-0000-4000-8000-000000000001';
select is(public.get_education_run('c1710000-0000-4000-8000-000000000001')->>'workerStatus','offline','Control heartbeat without readiness is unavailable');
update public.workers set health='{"executionReady":true}' where id='c1740000-0000-4000-8000-000000000001';
update public.jobs set status='running',stage='voice',worker_id='c1740000-0000-4000-8000-000000000001',worker_instance_id='c1740000-0000-4000-8000-000000000011',lease_token=1,last_heartbeat_at=now(),lease_expires_at=now()+interval '1 minute',started_at=now(),progress='{"completedScenes":2,"totalScenes":4}' where id='c1730000-0000-4000-8000-000000000001';
select is(public.get_education_run('c1710000-0000-4000-8000-000000000001')->'progress','{"completedScenes":2,"totalScenes":4}'::jsonb,'Counts come from durable progress');
select ok(public.get_education_run('c1710000-0000-4000-8000-000000000001')->>'startedAt' is not null,'Known start is provided');
select ok(abs(extract(epoch from (public.get_education_run('c1710000-0000-4000-8000-000000000001')->>'serverTime')::timestamptz-clock_timestamp()))<2,'Read uses current server time');
insert into public.workers(id,label,enabled,protocol_version,last_seen_at,capabilities,health) select 'c1740000-0000-4000-8000-000000000002','Unrelated live worker',true,1,now(),capabilities,health from public.workers where id='c1740000-0000-4000-8000-000000000001';
update public.jobs set lease_expires_at=now()-interval '1 second' where id='c1730000-0000-4000-8000-000000000001';
select is(public.get_education_run('c1710000-0000-4000-8000-000000000001')->>'workerStatus','offline','Unrelated online worker cannot conceal expired assigned lease');
select is((select status from public.jobs where id='c1730000-0000-4000-8000-000000000001'),'running','Progress reads do not reconcile or mutate jobs');
update public.jobs set status='waiting_quota',worker_id=null,worker_instance_id=null,lease_expires_at=null,last_heartbeat_at=null,retry_at=now()+interval '1 hour' where id='c1730000-0000-4000-8000-000000000001';
select is((public.get_education_run('c1710000-0000-4000-8000-000000000001')->>'retryAt')::timestamptz,(select retry_at from public.jobs where id='c1730000-0000-4000-8000-000000000001'),'Known provider eligibility is preserved exactly');
update public.jobs set retry_at=null where id='c1730000-0000-4000-8000-000000000001';
select is(public.get_education_run('c1710000-0000-4000-8000-000000000001')->'retryAt','null'::jsonb,'Unknown provider retry stays unknown');
update public.app_settings set claims_paused=true where id='global';
select is(public.get_education_run('c1710000-0000-4000-8000-000000000001')->>'claimsPaused','true','Actual claims pause is supplied');
select ok(public.get_education_run('c1710000-0000-4000-8000-000000000001')::text not like '%PRIVATE_PROGRESS_INPUT%' and not (public.get_education_run('c1710000-0000-4000-8000-000000000001') ?| array['workerId','objectKey','health','input','token','leaseToken']),'Progress exposes no private input, storage or worker credential details');
select set_config('request.jwt.claims','{"sub":"c1700000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.get_education_run('c1710000-0000-4000-8000-000000000001')$$,'42501',null::text,'Other owner cannot read progress');
select set_config('request.jwt.claims','{"sub":"c1700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
update public.profiles set status='disabled' where id='c1700000-0000-4000-8000-000000000001';
select throws_ok($$select public.get_education_run('c1710000-0000-4000-8000-000000000001')$$,'42501',null::text,'Disabled account cannot read progress');
select * from finish();rollback;
